import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { uv, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { primitives } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{text:string,role?:string,typography?:{fontSize?:number}}>} [textContent]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = 'FeaturesNode';
  root.userData.handlers = {};

  // ---------- Backdrop Plane ----------
  const atlasRegion = { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlasRegion.width / atlasRegion.height; // 1.6
  const planeGeom = new PlaneGeometry(aspect, 1);
  const planeMat = new MeshBasicNodeMaterial();

  // Apply UV node to select atlas region (if needed)
  const uvNode = uv();
  // Assuming full texture atlas; if atlas size is larger, adjust with mul/add here.
  planeMat.map = null; // will be set after texture load
  planeMat.uv = uvNode; // assign UV node (no offset/scale needed for full texture)

  const planeMesh = new Mesh(planeGeom, planeMat);
  planeMesh.name = 'FeaturesPlane';
  // Billboard toward camera: we will update on each frame via a simple onBeforeRender hook
  planeMesh.onBeforeRender = (renderer, scene, camera) => {
    const camPos = camera.position;
    planeMesh.lookAt(camPos);
  };
  root.add(planeMesh);

  // Load texture asynchronously (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = item.text || '';
    const fontSize = item.typography?.fontSize ?? 96;
    const color = config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2';
    const textObj = ctx.fontAtlas.createText(txt, {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly in front of plane
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // ---------- Cinematic Primitives ----------
  const primitivesRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitivesRefs.push(instance);
        // Attach trigger handling if needed (not required for this node)
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose any loaded texture (if we kept reference)
    // texture is managed by loader cache; we don't dispose here to avoid double free

    // Cleanup primitives
    for (const p of primitivesRefs) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Kill any GSAP timelines (none created here)
    gsap.globalTimeline.clear();
  };

  return root;
}
